{"packet_id":"D026-01","doc_id":"D026","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California application screening fee cap","requirement":"A landlord or agent may charge a screening fee up to actual costs and no more than $30 per applicant (CPI-adjusted), must provide an itemized receipt, and must refund unused amounts and fees for unconsidered applications within 7 days.","key_value":"$30 per applicant, CPI-adjusted annually since January 1, 1998","coverage_conditions":"All residential rental property in California; applies to any landlord (owner of residential rental property) or their agent who receives a rental application and charges an application screening fee.","applicability":{"conditions":[],"per_tenancy":"Applies when a landlord or agent receives a request to rent residential property and charges an application screening fee; fee may not be charged if no rental unit is available or will be available within a reasonable time.","coverage_quotes":[]},"exemptions":"No refund is required for an applicant denied after consideration because they do not meet the landlord’s established screening criteria.","penalty":null,"effective_date":"2026-01-01","valid_through":null,"citation":"Cal. Civ. Code § 1950.6","quoted_span":"In no case shall the amount of the application screening fee charged by the landlord or their agent be greater than thirty dollars ($30) per applicant.","interaction":"Does not preempt federal or state housing assistance program rules on collection of deposits and fees.","relations":[],"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D026-01","doc_id":"D026","jurisdiction":"CA","category":"screening_restrictions","lifecycle":"enacted","title":"California application screening process restrictions","requirement":"A landlord or agent charging a fee must consider completed applications in order received under written screening criteria, approve the first qualified applicant, not charge unless the application is considered, and provide a credit report within 7 days.","key_value":"First qualified applicant; 7-day refund; 7-day credit report","coverage_conditions":"All residential rental property in California; applies to any landlord (owner of residential rental property) or their agent who receives a rental application and charges an application screening fee.","applicability":{"conditions":[],"per_tenancy":"Applies when a landlord or agent charges an application screening fee after receiving a rental application; the fee may only be charged if the application is actually considered.","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026-01-01","valid_through":null,"citation":"Cal. Civ. Code § 1950.6","quoted_span":"Completed applications are considered, as provided for in the landlord’s established screening criteria, in the order in which the completed applications were received. The landlord’s screening criteria shall be provided to the applicant in writing together with the application form.","interaction":"Does not preempt federal or state housing assistance program rules on collection of deposits and fees.","relations":[],"confidence":0.95,"conflict_flag":false,"conflict_note":null}
